'use strict';
const $=s=>document.querySelector(s);
const scenes=window.MUSEUM_SCENES, works=window.MUSEUM_ARTWORKS;
const order=['scene_7','scene_8','scene_2','scene_9','scene_10','scene_6','scene_13','scene_11','scene_12','scene_1','scene_4','scene_3'];
const roomInfo={
 scene_7:{name:'展览厅 1',floor:'一楼展厅',note:'三毛的故事，从这里开始。',yaw:175},
 scene_8:{name:'展览厅 2',floor:'一楼展厅',note:'把目光留给那些小小的日常。',yaw:-70},
 scene_2:{name:'展览厅 3',floor:'一楼展厅',note:'墙上的童谣，藏着天马行空的想象。',yaw:-100},
 scene_9:{name:'展览厅 4',floor:'一楼展厅',note:'走近画框，看看笔下的大世界。',yaw:-145},
 scene_10:{name:'展览厅 5',floor:'一楼展厅',note:'看过故事，也看看大家留下的心意。',yaw:0},
 scene_6:{name:'一楼过道',floor:'一楼',note:'顺着箭头，走进下一个房间。',yaw:0},
 scene_13:{name:'二楼过道',floor:'二楼起居',note:'上楼，看看一家人的生活空间。',yaw:-30},
 scene_11:{name:'书房',floor:'二楼起居',note:'在熟悉的书桌旁，停留片刻。',yaw:0},
 scene_12:{name:'卧室',floor:'二楼起居',note:'漫画家也是这座小屋的家人。',yaw:0},
 scene_1:{name:'孩子房间',floor:'二楼起居',note:'小小房间里，装着一家人的童年。',yaw:0},
 scene_4:{name:'故居花园',floor:'户外',note:'到花园里，换一个角度看看小屋。',yaw:-40},
 scene_3:{name:'故居大门',floor:'户外',note:'五原路的小巷里，故事的门开着。',yaw:-120}
};
const related=[
 {id:'fashion',scene:'scene_7',ath:172,atv:25,kind:'case'},
 {id:'army',scene:'scene_8',ath:-2.53,atv:16.25,kind:'case'},
 {id:'alone',scene:'scene_2',ath:171.7,atv:20.1,kind:'case'},
 {id:'sharing',scene:'scene_2',ath:-21,atv:31,kind:'case'},
 {id:'running',scene:'scene_9',ath:23,atv:30,kind:'case'}
];
const anchors=[...works.filter(w=>w.matched).map(w=>({id:w.id,scene:w.scene,ath:w.ath,atv:w.atv,kind:'painting'})),...related];
const viewer=$('#viewer'),loading=$('.viewer-loading');
let scene=scenes.find(s=>s.id==='scene_2'),yaw=0,pitch=0,fov=76,renderer,camera,world,panorama;
let generation=0,activeHotspots=[],activeRegions=[],dragging=false,dragDistance=0,lastX=0,lastY=0,autoRotate=false,lastFrame=0,webglReady=false;
let currentWork=null,filter='all',roomFilter=null,toastTimer,activeTab='tour';
const cache=new Map(),pointerMap=new Map();let pinchDistance=0;
const radians=n=>n*Math.PI/180, degrees=n=>n*180/Math.PI;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function groupFor(s){if(['scene_7','scene_8','scene_2','scene_9','scene_10','scene_6'].includes(s))return '一楼';if(['scene_4','scene_3'].includes(s))return '户外';return '二楼';}
function renderRooms(){const list=$('#room-list');let group='';for(const id of order){const info=roomInfo[id],nextGroup=groupFor(id);if(group!==nextGroup){group=nextGroup;const h=document.createElement('p');h.className='room-group';h.textContent=group;list.append(h);}const b=document.createElement('button');b.className='room-button';b.dataset.scene=id;b.innerHTML=`<img src="assets/thumbs/${id}.jpg" alt="" loading="lazy"><span>${info.name}</span><span class="room-arrow">↗</span>`;b.onclick=()=>loadScene(scenes.find(s=>s.id===id));list.append(b);}}
function status(message,error=false){loading.classList.remove('hidden');loading.querySelector('p').textContent=message;$('#retry').hidden=!error;$('.loading-dots').hidden=error;}
function size(){if(!renderer)return;const w=viewer.clientWidth,h=viewer.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();$('#art-regions').setAttribute('viewBox',`0 0 ${w} ${h}`);}
function zoom(delta){fov=Math.max(38,Math.min(102,fov+delta));if(camera){camera.fov=fov;camera.updateProjectionMatrix();}}
function resetView(){yaw=radians(roomInfo[scene.id].yaw);pitch=radians(scene.id==='scene_2'?2:0);fov=76;zoom(0);}
function stopRotation(){autoRotate=false;$('#rotate').classList.remove('is-active');$('#rotate').setAttribute('aria-label','开始自动环顾');}
function init3D(){world=new THREE.Scene();camera=new THREE.PerspectiveCamera(fov,1,.1,2000);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));renderer.outputEncoding=THREE.sRGBEncoding;viewer.append(renderer.domElement);webglReady=true;new ResizeObserver(size).observe(viewer);renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();status('画面暂时中断，请重新加载。',true);});size();requestAnimationFrame(animate);}
function loadImage(url){return new Promise((resolve,reject)=>{const image=new Image();const timer=setTimeout(()=>reject(new Error('图片加载超时')),20000);image.onload=()=>{clearTimeout(timer);resolve(image);};image.onerror=()=>{clearTimeout(timer);reject(new Error('图片暂时没有加载成功'));};image.src=url;});}
async function makeFace(key,s){const tiles=s.faces[key],images=await Promise.all(tiles.map(t=>loadImage(t.url)));const c=document.createElement('canvas');c.width=c.height=s.faceSize;const ctx=c.getContext('2d');images.forEach((im,i)=>ctx.drawImage(im,tiles[i].x,tiles[i].y));const texture=new THREE.CanvasTexture(c);texture.encoding=THREE.sRGBEncoding;const mesh=new THREE.Mesh(new THREE.PlaneGeometry(1000,1000),new THREE.MeshBasicMaterial({map:texture}));if(key==='f')mesh.position.z=-500;if(key==='b'){mesh.position.z=500;mesh.rotation.y=Math.PI;}if(key==='r'){mesh.position.x=500;mesh.rotation.y=-Math.PI/2;}if(key==='l'){mesh.position.x=-500;mesh.rotation.y=Math.PI/2;}if(key==='u'){mesh.position.y=500;mesh.rotation.x=Math.PI/2;}if(key==='d'){mesh.position.y=-500;mesh.rotation.x=-Math.PI/2;}return mesh;}
function dispose(group){if(!group)return;group.children.forEach(m=>{m.geometry.dispose();m.material.map.dispose();m.material.dispose();});if(world)world.remove(group);}
async function loadScene(next,view){if(!next)return;scene=next;const token=++generation;stopRotation();viewer.dataset.state='loading';status('正在走进'+roomInfo[next.id].name+'…');updateSceneUI();if(!webglReady){const fallback=$('.fallback-image')||Object.assign(document.createElement('img'),{className:'fallback-image'});fallback.src=`assets/thumbs/${next.id}.jpg`;viewer.append(fallback);status('当前浏览器无法显示全景，请使用支持 WebGL 的浏览器。作品小馆仍可浏览。',false);return;}
 try{let group=cache.get(next.id);if(!group){group=new THREE.Group();const results=await Promise.allSettled('frblud'.split('').map(k=>makeFace(k,next)));results.forEach(r=>{if(r.status==='fulfilled')group.add(r.value);});const error=results.find(r=>r.status==='rejected');if(error){dispose(group);throw error.reason;}if(token!==generation){dispose(group);return;}cache.set(next.id,group);}if(token!==generation)return;if(panorama)world.remove(panorama);panorama=group;world.add(group);cache.delete(next.id);cache.set(next.id,group);while(cache.size>3){const old=cache.keys().next().value;dispose(cache.get(old));cache.delete(old);}resetView();if(view){yaw=radians(view.ath);pitch=radians(view.atv);fov=65;zoom(0);}viewer.dataset.state='ready';loading.classList.add('hidden');size();}catch(error){if(token===generation){viewer.dataset.state='error';status(error.message+'，点一下再试试。',true);}}}
function pointAt(h,v){const a=radians(h),b=radians(v);return new THREE.Vector3(Math.sin(a)*Math.cos(b),-Math.sin(b),-Math.cos(a)*Math.cos(b));}
function project(p){p=p.clone().applyMatrix4(camera.matrixWorldInverse);const ahead=p.z<-.05;p.applyMatrix4(camera.projectionMatrix);return {x:(p.x+1)*.5*viewer.clientWidth,y:(1-p.y)*.5*viewer.clientHeight,visible:ahead&&Math.abs(p.x)<1.1&&Math.abs(p.y)<1.1};}
function animate(time){requestAnimationFrame(animate);const elapsed=Math.min((time-lastFrame)/1000,.05);lastFrame=time;if(activeTab!=='tour'||!viewer.clientWidth)return;if(autoRotate&&!dragging&&!$('#art-dialog').open&&!$('#about-dialog').open)yaw+=elapsed*.055;camera.rotation.order='YXZ';camera.rotation.y=-yaw;camera.rotation.x=-pitch;camera.updateMatrixWorld();renderer.render(world,camera);const ready=viewer.dataset.state==='ready';for(const h of activeHotspots){const p=project(h.point);h.button.hidden=!ready||!p.visible;h.button.style.left=p.x+'px';h.button.style.top=p.y+'px';}for(const r of activeRegions){const points=r.points.map(project);const visible=ready&&points.every(p=>p.visible);r.element.style.display=visible?'':'none';if(visible)r.element.setAttribute('points',points.map(p=>`${p.x},${p.y}`).join(' '));}}
function updateSceneUI(){const info=roomInfo[scene.id];$('#scene-title').textContent=info.name;$('#scene-floor').textContent=info.floor;$('#scene-description').textContent=info.note;$('#scene-position').textContent=String(order.indexOf(scene.id)+1).padStart(2,'0')+' / 12';document.querySelectorAll('.room-button').forEach(b=>{const active=b.dataset.scene===scene.id;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'location':'false');});const roomWorks=anchors.filter(a=>a.scene===scene.id);$('#room-art-count').textContent=roomWorks.length;$('#room-artworks').hidden=!roomWorks.length;$('#hotspots').replaceChildren();$('#art-regions').replaceChildren();activeHotspots=[];activeRegions=[];
 for(const h of scene.hotspots){if(!h.linkedscene||h.linkedscene===scene.id)continue;const target=scenes.find(s=>s.id===h.linkedscene);if(!target)continue;const button=document.createElement('button');button.className='hotspot nav-hotspot';button.setAttribute('aria-label','走到'+roomInfo[target.id].name);button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 14 7-7 7 7m-14 5 7-7 7 7"/></svg><span class="hotspot-label">'+roomInfo[target.id].name+'</span>';button.onclick=()=>loadScene(target);button.hidden=true;$('#hotspots').append(button);if(webglReady)activeHotspots.push({button,point:pointAt(Number(h.ath),Number(h.atv))});}
 for(const a of roomWorks){const work=works.find(w=>w.id===a.id);const button=document.createElement('button');button.className='hotspot art-hotspot';button.setAttribute('aria-label','查看作品：'+work.title);button.dataset.art=work.id;button.innerHTML='＋<span class="hotspot-label">'+work.title+'</span>';button.onclick=()=>openArt(work.id);button.hidden=true;$('#hotspots').append(button);if(webglReady){activeHotspots.push({button,point:pointAt(a.ath,a.atv)});const polygon=document.createElementNS('http://www.w3.org/2000/svg','polygon');polygon.dataset.art=work.id;const width=a.kind==='case'?14:(['hen','peas','corn'].includes(a.id)?4.5:7),height=a.kind==='case'?6:(['hen','peas','corn'].includes(a.id)?3.2:6);const corners=[[-width,-height],[width,-height],[width,height],[-width,height]].map(([h,v])=>pointAt(a.ath+h,a.atv+v));polygon.addEventListener('click',()=>{if(dragDistance<7)openArt(work.id);});$('#art-regions').append(polygon);activeRegions.push({element:polygon,points:corners});}}
}
function setupPointers(){viewer.addEventListener('pointerdown',e=>{if(e.target.closest('button,a')||viewer.dataset.state!=='ready')return;stopRotation();pointerMap.set(e.pointerId,{x:e.clientX,y:e.clientY});dragging=true;dragDistance=0;lastX=e.clientX;lastY=e.clientY;viewer.focus({preventScroll:true});if(e.target.tagName!=='polygon')viewer.setPointerCapture(e.pointerId);if(pointerMap.size===2){const p=[...pointerMap.values()];pinchDistance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);}});viewer.addEventListener('pointermove',e=>{if(!dragging||!pointerMap.has(e.pointerId))return;pointerMap.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointerMap.size===2){const p=[...pointerMap.values()],dist=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);zoom((pinchDistance-dist)*.12);pinchDistance=dist;dragDistance+=10;}else{const dx=e.clientX-lastX,dy=e.clientY-lastY;yaw-=dx*.003;pitch=Math.max(-1.35,Math.min(1.35,pitch+dy*.003));dragDistance+=Math.abs(dx)+Math.abs(dy);}lastX=e.clientX;lastY=e.clientY;});const end=e=>{pointerMap.delete(e.pointerId);if(pointerMap.size){const p=[...pointerMap.values()][0];lastX=p.x;lastY=p.y;}else dragging=false;};['pointerup','pointercancel','lostpointercapture'].forEach(ev=>viewer.addEventListener(ev,end));['pointerup','pointercancel'].forEach(ev=>window.addEventListener(ev,end));window.addEventListener('blur',()=>{pointerMap.clear();dragging=false;});viewer.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY*.035);},{passive:false});viewer.addEventListener('keydown',e=>{if(e.target!==viewer)return;const handlers={ArrowLeft:()=>yaw-=.1,ArrowRight:()=>yaw+=.1,ArrowUp:()=>pitch=Math.max(-1.35,pitch-.08),ArrowDown:()=>pitch=Math.min(1.35,pitch+.08),'+':()=>zoom(-7),'-':()=>zoom(7),'=':()=>zoom(-7)};if(handlers[e.key]){e.preventDefault();stopRotation();handlers[e.key]();}});}
function showTab(name){activeTab=name==='collection'?'collection':'tour';$('#tour-page').hidden=activeTab!=='tour';$('#collection-page').hidden=activeTab!=='collection';document.querySelectorAll('[data-tab]').forEach(a=>{const active=a.dataset.tab===activeTab;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});if(activeTab==='tour')requestAnimationFrame(size);else renderGallery();}
function applyRoute(){showTab(location.hash==='#collection'?'collection':'tour');}
function inCategory(w){if(filter==='all')return true;if(filter==='onsite')return !!w.matched;if(filter==='early')return ['fashion','reuse'].includes(w.id);if(filter==='wandering')return ['army','doorbell','alone','sharing'].includes(w.id);return !w.matched&&!['fashion','reuse','army','doorbell','alone','sharing'].includes(w.id);}
function renderGallery(){const box=$('#artwork-grid');box.replaceChildren();const filtered=works.filter(w=>inCategory(w)&&(!roomFilter||anchors.some(a=>a.id===w.id&&a.scene===roomFilter)));$('#clear-room-filter').hidden=!roomFilter;$('#clear-room-filter').textContent=roomFilter?roomInfo[roomFilter].name+' · 查看全部 ×':'';for(const w of filtered){const button=document.createElement('button');button.className='art-card';button.dataset.art=w.id;button.innerHTML=`<div class="art-card-image"><img src="${w.image}" alt="${w.title}" loading="lazy"><span class="card-plus" aria-hidden="true">＋</span></div><h2>${w.title}</h2><p>${w.series}<span>${w.year}</span></p>`;button.onclick=()=>openArt(w.id);box.append(button);}if(!filtered.length){const p=document.createElement('p');p.className='empty-state';p.textContent='这个分类暂时没有作品，试试「全部作品」。';box.append(p);}}
function openArt(id){const w=works.find(a=>a.id===id);if(!w)return;stopRotation();currentWork=w;$('#art-image').src=w.image;$('#art-image').alt=w.title;$('#art-series').textContent=w.series;$('#art-title').textContent=w.title;$('#art-year').textContent=w.year;$('#art-description').textContent=w.description;$('#art-source-link').href=w.sourceUrl;$('.art-source span').textContent=w.matched?'展厅作品 · 官网图像':(anchors.some(a=>a.id===w.id)?'展柜延伸阅读 · 官网选页':'三毛漫画 · 官网选页');const anchor=anchors.find(a=>a.id===w.id);$('#locate-art').hidden=!anchor;$('#locate-art').innerHTML=w.matched?'回到这幅画 <span>→</span>':'去展柜看看 <span>→</span>';if(!$('#art-dialog').open)$('#art-dialog').showModal();}
function closeOnBackdrop(dialog){dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});dialog.querySelector('.dialog-close').onclick=()=>dialog.close();}
document.querySelectorAll('dialog').forEach(closeOnBackdrop);
$('#next-art').onclick=()=>{let list=activeTab==='collection'?works.filter(w=>inCategory(w)&&(!roomFilter||anchors.some(a=>a.id===w.id&&a.scene===roomFilter))):works;if(activeTab==='tour'){const ids=anchors.filter(a=>a.scene===scene.id).map(a=>a.id);list=works.filter(w=>ids.includes(w.id));}if(!list.some(w=>w.id===currentWork.id))list=works;openArt(list[(list.findIndex(w=>w.id===currentWork.id)+1)%list.length].id);};
$('#locate-art').onclick=()=>{const a=anchors.find(a=>a.id===currentWork.id);if(!a)return;$('#art-dialog').close();location.hash='tour';showTab('tour');loadScene(scenes.find(s=>s.id===a.scene),a);};
$('#image-zoom').onclick=()=>{$('#large-art').src=currentWork.image;$('#large-art').alt=currentWork.title;$('#image-dialog').showModal();};
$('#about-open').onclick=$('#sources-open').onclick=()=>{$('#about-dialog').showModal();stopRotation();};
$('#zoom-in').onclick=()=>zoom(-8);$('#zoom-out').onclick=()=>zoom(8);$('#reset').onclick=()=>{stopRotation();resetView();};$('#retry').onclick=()=>{if(webglReady)loadScene(scene);else location.reload();};
$('#rotate').onclick=()=>{autoRotate=!autoRotate;$('#rotate').classList.toggle('is-active',autoRotate);$('#rotate').setAttribute('aria-label',autoRotate?'暂停自动环顾':'开始自动环顾');};
$('#dismiss-tip').onclick=()=>$('#viewer-tip').hidden=true;
$('#previous-room').onclick=()=>loadScene(scenes.find(s=>s.id===order[(order.indexOf(scene.id)-1+order.length)%order.length]));$('#next-room').onclick=()=>loadScene(scenes.find(s=>s.id===order[(order.indexOf(scene.id)+1)%order.length]));
$('#room-artworks').onclick=()=>{roomFilter=scene.id;filter='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));location.hash='collection';showTab('collection');};
$('#clear-room-filter').onclick=()=>{roomFilter=null;renderGallery();};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderGallery();});
document.querySelector('[data-tab="collection"]').addEventListener('click',()=>{roomFilter=null;filter='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));renderGallery();});
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(viewer.requestFullscreen)await viewer.requestFullscreen();else viewer.classList.toggle('full-window');}catch{viewer.classList.toggle('full-window');}$('#fullscreen').setAttribute('aria-label',document.fullscreenElement||viewer.classList.contains('full-window')?'退出全屏':'全屏漫游');size();};
document.addEventListener('fullscreenchange',()=>{size();$('#fullscreen').setAttribute('aria-label',document.fullscreenElement?'退出全屏':'全屏漫游');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&viewer.classList.contains('full-window')){viewer.classList.remove('full-window');size();}});
window.addEventListener('hashchange',applyRoute);
renderRooms();setupPointers();applyRoute();try{init3D();}catch(error){webglReady=false;console.warn('Panorama unavailable:',error.message);}loadScene(scene);
